//! RDB-003: a function's cognitive complexity stays within bounds (Rust).
//!
//! **What this judges (Rust, from the source alone):** for every function with a body (a free function, a method of an `impl`, a default
//! method of a trait, a nested function), outside vendored directories, `tests/`, `examples/`, `benches/`, `build.rs`, `#[cfg(test)]`
//! items, `#[test]` functions and files that say they are generated (`@generated`, `DO NOT EDIT` or `generated by` in the first
//! lines), the score of SonarSource's *Cognitive Complexity* (G. Ann Campbell, 2017, the measure the record names) is computed with `syn`:
//!
//! - **+1 plus the nesting level** for each `if` / `if let`, each `match`, and each `for`, `while` and `loop`;
//! - **+1** (no nesting increment) for each `else` and each `else if`;
//! - **+1** for each sequence of like logical operators in an expression (`a && b && c` is one, `a && b || c` is two);
//! - **+1** for a `break` or `continue` that names a label;
//! - **+1** for each direct recursive call (`name(..)` or `self.name(..)` inside `name`);
//! - **nesting** goes up by one inside an `if`, `else`, `match` arm, loop body and closure body; a closure adds no increment itself.
//!
//! A function over **15** is reported (Low severity), over **30** is Medium: the two levels the record names ("a warning level near 15
//! and an error level near 30"). One finding per function, at its name, with the score. Medium confidence.
//!
//! **Not judged:** the record's second half ("a function being edited should not become more complex than it was") needs a baseline
//! at the merge base, which this reading does not have; the `?` operator and `unsafe` blocks add nothing (as in the measure); a
//! `match` counts once however many arms it has; macro bodies (`syn` does not look inside a macro's tokens, so an `if` written in
//! `vec![..]` or `assert!(..)` arguments is not seen); generated code that does not say so; other languages. A file `syn` cannot parse is
//! named in a note, never read as clean. Parsers and state machines score high by nature: allow them with a reason.

use super::rust_package::{load, unparsed_note};
use super::{RepoView, Verdict};
use crate::checks::size_coupling::is_cfg_test;
use crate::finding::{Confidence, Finding, Location, Severity};
use syn::visit::Visit;
use syn::{BinOp, Expr, ExprIf, ImplItemFn, ItemFn, ItemMod, TraitItemFn};

const ID: &str = crate::rule_id::RDB_003;

/// The score above which a function is reported (the record's "warning level near 15").
const WARN: u32 = 15;
/// The score above which the finding is Medium (the record's "error level near 30").
const ERROR: u32 = 30;

fn line_of(span: proc_macro2::Span) -> u32 {
    u32::try_from(span.start().line).unwrap_or(0)
}

fn has_test_attr(attrs: &[syn::Attribute]) -> bool {
    attrs.iter().any(|a| {
        a.path()
            .segments
            .last()
            .is_some_and(|s| s.ident == "test" || s.ident == "bench")
    })
}

fn is_generated(text: &str) -> bool {
    text.lines().take(8).any(|l| {
        let l = l.to_ascii_lowercase();
        l.contains("@generated") || l.contains("do not edit") || l.contains("generated by")
    })
}

/// The cognitive-complexity score of one function body.
struct Score<'a> {
    name: &'a str,
    nesting: u32,
    total: u32,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Op {
    And,
    Or,
}

/// Flatten a tree of `&&` and `||` (through parentheses) into the operators in source order and the operand expressions.
fn logic<'e>(e: &'e Expr, ops: &mut Vec<Op>, leaves: &mut Vec<&'e Expr>) {
    match e {
        Expr::Binary(b) if matches!(b.op, BinOp::And(_) | BinOp::Or(_)) => {
            logic(&b.left, ops, leaves);
            ops.push(if matches!(b.op, BinOp::And(_)) {
                Op::And
            } else {
                Op::Or
            });
            logic(&b.right, ops, leaves);
        }
        Expr::Paren(p) if matches!(&*p.expr, Expr::Binary(b) if matches!(b.op, BinOp::And(_) | BinOp::Or(_))) =>
        {
            logic(&p.expr, ops, leaves);
        }
        other => leaves.push(other),
    }
}

impl Score<'_> {
    fn nested<F: FnOnce(&mut Self)>(&mut self, f: F) {
        self.nesting += 1;
        f(self);
        self.nesting -= 1;
    }

    /// An `if` and its `else if` / `else` chain.
    fn if_chain(&mut self, i: &ExprIf) {
        self.total += 1 + self.nesting;
        self.visit_expr(&i.cond);
        self.nested(|s| s.visit_block(&i.then_branch));
        let mut next = i.else_branch.as_ref().map(|(_, e)| &**e);
        while let Some(e) = next {
            match e {
                Expr::If(ei) => {
                    self.total += 1;
                    self.visit_expr(&ei.cond);
                    self.nested(|s| s.visit_block(&ei.then_branch));
                    next = ei.else_branch.as_ref().map(|(_, e)| &**e);
                }
                other => {
                    self.total += 1;
                    self.nested(|s| s.visit_expr(other));
                    next = None;
                }
            }
        }
    }
}

impl<'ast> Visit<'ast> for Score<'_> {
    fn visit_expr(&mut self, e: &'ast Expr) {
        match e {
            Expr::If(i) => self.if_chain(i),
            Expr::Match(m) => {
                self.total += 1 + self.nesting;
                self.visit_expr(&m.expr);
                self.nested(|s| {
                    for arm in &m.arms {
                        syn::visit::visit_arm(s, arm);
                    }
                });
            }
            Expr::ForLoop(f) => {
                self.total += 1 + self.nesting;
                self.visit_expr(&f.expr);
                self.nested(|s| s.visit_block(&f.body));
            }
            Expr::While(w) => {
                self.total += 1 + self.nesting;
                self.visit_expr(&w.cond);
                self.nested(|s| s.visit_block(&w.body));
            }
            Expr::Loop(l) => {
                self.total += 1 + self.nesting;
                self.nested(|s| s.visit_block(&l.body));
            }
            Expr::Closure(c) => {
                self.nested(|s| s.visit_expr(&c.body));
            }
            Expr::Break(b) => {
                if b.label.is_some() {
                    self.total += 1;
                }
                if let Some(v) = &b.expr {
                    self.visit_expr(v);
                }
            }
            Expr::Continue(c) => {
                if c.label.is_some() {
                    self.total += 1;
                }
            }
            Expr::Binary(b) if matches!(b.op, BinOp::And(_) | BinOp::Or(_)) => {
                let mut ops = Vec::new();
                let mut leaves = Vec::new();
                logic(e, &mut ops, &mut leaves);
                let changes = ops.windows(2).filter(|w| w[0] != w[1]).count();
                self.total += 1 + u32::try_from(changes).unwrap_or(0);
                for l in leaves {
                    self.visit_expr(l);
                }
            }
            Expr::Call(c) => {
                if let Expr::Path(p) = &*c.func {
                    if p.qself.is_none() && p.path.is_ident(self.name) {
                        self.total += 1;
                    }
                }
                syn::visit::visit_expr_call(self, c);
            }
            Expr::MethodCall(m) => {
                if m.method == self.name
                    && matches!(&*m.receiver, Expr::Path(p) if p.path.is_ident("self"))
                {
                    self.total += 1;
                }
                syn::visit::visit_expr_method_call(self, m);
            }
            other => syn::visit::visit_expr(self, other),
        }
    }

    // A nested function is scored on its own.
    fn visit_item_fn(&mut self, _: &'ast ItemFn) {}
    fn visit_item_impl(&mut self, _: &'ast syn::ItemImpl) {}
}

fn score(name: &str, block: &syn::Block) -> u32 {
    let mut s = Score {
        name,
        nesting: 0,
        total: 0,
    };
    s.visit_block(block);
    s.total
}

struct Site {
    name: String,
    line: u32,
    score: u32,
}

#[derive(Default)]
struct Collect {
    owner: Vec<String>,
    sites: Vec<Site>,
    in_test: bool,
}

impl Collect {
    fn fn_site(&mut self, ident: &syn::Ident, block: &syn::Block) {
        let s = score(&ident.to_string(), block);
        if s > WARN {
            let name = if self.owner.is_empty() {
                ident.to_string()
            } else {
                format!("{}::{}", self.owner.join("::"), ident)
            };
            self.sites.push(Site {
                name,
                line: line_of(ident.span()),
                score: s,
            });
        }
    }
}

impl<'ast> Visit<'ast> for Collect {
    fn visit_item_mod(&mut self, i: &'ast ItemMod) {
        let before = self.in_test;
        if is_cfg_test(&i.attrs) {
            self.in_test = true;
        }
        syn::visit::visit_item_mod(self, i);
        self.in_test = before;
    }

    fn visit_item_fn(&mut self, i: &'ast ItemFn) {
        if !self.in_test && !is_cfg_test(&i.attrs) && !has_test_attr(&i.attrs) {
            self.fn_site(&i.sig.ident, &i.block);
            syn::visit::visit_item_fn(self, i);
        }
    }

    fn visit_item_impl(&mut self, i: &'ast syn::ItemImpl) {
        if self.in_test || is_cfg_test(&i.attrs) {
            return;
        }
        let owner = match &*i.self_ty {
            syn::Type::Path(p) => p
                .path
                .segments
                .last()
                .map(|s| s.ident.to_string())
                .unwrap_or_default(),
            _ => String::new(),
        };
        self.owner.push(owner);
        syn::visit::visit_item_impl(self, i);
        self.owner.pop();
    }

    fn visit_impl_item_fn(&mut self, i: &'ast ImplItemFn) {
        if !self.in_test && !is_cfg_test(&i.attrs) && !has_test_attr(&i.attrs) {
            self.fn_site(&i.sig.ident, &i.block);
            syn::visit::visit_impl_item_fn(self, i);
        }
    }

    fn visit_item_trait(&mut self, i: &'ast syn::ItemTrait) {
        if self.in_test || is_cfg_test(&i.attrs) {
            return;
        }
        self.owner.push(i.ident.to_string());
        syn::visit::visit_item_trait(self, i);
        self.owner.pop();
    }

    fn visit_trait_item_fn(&mut self, i: &'ast TraitItemFn) {
        if let Some(b) = &i.default {
            if !self.in_test && !is_cfg_test(&i.attrs) {
                self.fn_site(&i.sig.ident, b);
            }
        }
        syn::visit::visit_trait_item_fn(self, i);
    }
}

pub(super) fn judge(view: &RepoView) -> Verdict {
    let loaded = load(view);
    if loaded.packages.is_empty() {
        return Verdict::NotApplicable(
            "the repository tracks no Rust package source outside tests, examples and vendored trees".into(),
        );
    }
    let mut findings = Vec::new();
    for p in &loaded.packages {
        let mut functions_read = 0usize;
        for s in &p.sources {
            if is_generated(&s.text) {
                continue;
            }
            functions_read += s.text.matches("fn ").count();
            let mut c = Collect::default();
            c.visit_file(&s.file);
            for site in c.sites {
                let severity = if site.score > ERROR {
                    Severity::Medium
                } else {
                    Severity::Low
                };
                findings.push(
                    Finding::new(
                        ID,
                        severity,
                        Confidence::Medium,
                        view.name(),
                        format!(
                            "`{}` has cognitive complexity {} (warning above {WARN}, error above {ERROR})",
                            site.name, site.score
                        ),
                        "Flatten the control flow by exiting early on the failure cases, and pull out pieces that deserve a name. A parser or a state machine may be exempted with a recorded reason (an allowlist entry).",
                    )
                    .location(Location::new(s.path.as_str(), Some(site.line)))
                    .subject(site.name)
                    .positive_control(format!(
                        "{} Rust source file(s) of the package were scored with the same walk (about {functions_read} `fn` tokens in the files read so far)",
                        p.sources.len()
                    )),
                );
            }
        }
    }
    findings.sort_by(|a, b| {
        let key = |f: &Finding| {
            f.location
                .as_ref()
                .map(|l| (l.file.clone(), l.line))
                .unwrap_or_default()
        };
        key(a).cmp(&key(b))
    });
    match unparsed_note(ID, &loaded.unparsed) {
        Some(note) => Verdict::Noted(findings, vec![note]),
        None => Verdict::Findings(findings),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn score_of(body: &str) -> u32 {
        let f: syn::ItemFn = syn::parse_str(&format!("fn f() {{ {body} }}")).unwrap();
        score("f", &f.block)
    }

    #[test]
    fn straight_line_code_scores_zero_and_a_single_if_one() {
        assert_eq!(score_of("let a = 1; let b = a + 2;"), 0);
        assert_eq!(score_of("if x { y(); }"), 1);
    }

    #[test]
    fn nesting_adds_to_each_structure() {
        // if +1, nested if +2, nested for inside +3
        assert_eq!(score_of("if a { if b { for i in c { d(); } } }"), 6);
    }

    #[test]
    fn else_and_else_if_add_one_each_without_nesting() {
        assert_eq!(
            score_of("if a { x(); } else if b { y(); } else { z(); }"),
            3
        );
    }

    #[test]
    fn a_match_counts_once_and_sequences_of_logical_operators_count_by_change() {
        assert_eq!(score_of("match a { 1 => x(), 2 => y(), _ => z() }"), 1);
        assert_eq!(score_of("if a && b && c { x(); }"), 2);
        assert_eq!(score_of("if a && b || c { x(); }"), 3);
    }

    #[test]
    fn a_closure_adds_nesting_but_no_increment_and_a_labelled_break_counts() {
        assert_eq!(score_of("let g = || { if a { x(); } };"), 2);
        assert_eq!(score_of("'o: loop { loop { break 'o; } }"), 1 + 2 + 1);
    }

    #[test]
    fn a_direct_recursive_call_counts() {
        assert_eq!(score_of("f();"), 1);
    }

    fn found(src: &str) -> Vec<Finding> {
        match judge(&RepoView::from_files(&[
            (
                "Cargo.toml",
                "[package]\nname = \"p\"\nversion = \"0.1.0\"\n",
            ),
            ("src/lib.rs", src),
        ])) {
            Verdict::Findings(f) | Verdict::Noted(f, _) => f,
            Verdict::NotApplicable(r) => panic!("not applicable: {r}"),
        }
    }

    #[test]
    fn only_a_function_above_the_warning_level_is_reported_and_tests_are_skipped() {
        let deep = "if a { if b { if c { if d { if e { x(); } } } } }";
        let src = format!("fn big() {{ {deep} }}\nfn small() {{ if a {{ x(); }} }}\n#[cfg(test)]\nmod t {{ fn big() {{ {deep} }} }}\n");
        // 1 + 2 + 3 + 4 + 5 = 15 is not over the level; one more nesting is
        assert!(found(&src).is_empty());
        let deeper = "if a { if b { if c { if d { if e { if f { x(); } } } } } }";
        let f = found(&format!("fn big() {{ {deeper} }}\nfn small() {{}}\n"));
        assert_eq!(f.len(), 1);
        assert!(f[0].summary.contains("complexity 21"));
    }

    #[test]
    fn a_generated_file_is_not_read() {
        let deeper = "if a { if b { if c { if d { if e { if f { x(); } } } } } }";
        assert!(found(&format!("// @generated by tool\nfn big() {{ {deeper} }}\n")).is_empty());
    }
}
